import os,stat,json,hashlib,signal,zlib
from datetime import datetime,timezone
out={'schema':'tb371fc-android-trace-probe-capabilities-v1','captured_utc':datetime.now(timezone.utc).isoformat(),'kernel':os.uname().release,'scope':'compiled booleans and fixed interface metadata only; no BPF/perf/probe syscall or attachment','config':{}}
def timeout(*args):raise TimeoutError('metadata deadline')
signal.signal(signal.SIGALRM,timeout)
try:
 signal.setitimer(signal.ITIMER_REAL,1)
 with open('/proc/config.gz','rb') as f:b=f.read(1048577)
 if len(b)>1048576:raise ValueError('compressed config bound')
 d=zlib.decompressobj(16+zlib.MAX_WBITS);t=d.decompress(b,2097153)
 if len(t)>2097152 or not d.eof or d.unconsumed_tail:raise ValueError('config expansion bound')
 lines=t.decode().splitlines()
 for key in ['CONFIG_BPF_SYSCALL','CONFIG_BPF_EVENTS','CONFIG_BPF_JIT','CONFIG_KPROBES','CONFIG_KPROBE_EVENTS','CONFIG_PERF_EVENTS']:
  vals=[v for v in lines if v.startswith(key+'=') or v=='# '+key+' is not set']
  out['config'][key]={'matching_lines':vals,'enabled':vals==[key+'=y'],'known_boolean':vals in ([key+'=y'],['# '+key+' is not set'])}
 out['config_source']={'path':'/proc/config.gz','compressed_bytes':len(b),'compressed_sha256':hashlib.sha256(b).hexdigest(),'decoded_bytes':len(t),'decoded_sha256':hashlib.sha256(t).hexdigest(),'raw_content_published':False}
 out['config_status']='observed'
except Exception as e:out['config_status']='unavailable';out['error_type']=type(e).__name__;out['errno']=getattr(e,'errno',None)
finally:signal.setitimer(signal.ITIMER_REAL,0)
p='/sys/bus/event_source/devices/kprobe/type'
out['kprobe_type']={'path':p,'value_read':False}
try:
 signal.setitimer(signal.ITIMER_REAL,1)
 s=os.stat(p)
 out['kprobe_type'].update(exists=True,regular=stat.S_ISREG(s.st_mode),mode=oct(stat.S_IMODE(s.st_mode)),status='observed')
except FileNotFoundError:out['kprobe_type'].update(exists=False,status='absent')
except Exception as e:out['kprobe_type'].update(exists=None,status='unavailable',error_type=type(e).__name__,errno=getattr(e,'errno',None))
finally:signal.setitimer(signal.ITIMER_REAL,0)
out['actions']={'bpf_program_loaded':False,'bpf_map_created':False,'perf_event_open_called':False,'probe_attached':False,'trace_instance_created':False,'kernel_memory_read':False,'module_loaded':False,'sysctl_written':False,'debugfs_mounted':False,'radio_restart_or_qmi_call':False}
print(json.dumps(out))
